function SetDifficulty(tDifficulty)
   {
      var _loc3_ = 1;
      var _loc2_ = 1;
      if(World.CWorld.mGameMode == "DeathMatch")
      {
         _loc2_ = 200;
      }
      else
      {
         switch(tDifficulty)
         {
            case 0:
               _loc3_ = 1;
               _loc2_ = 1;
               break;
            case 1:
               _loc3_ = 10;
               _loc2_ = 10;
               break;
            case 2:
               _loc3_ = 20;
               _loc2_ = 30;
               break;
            case 3:
               _loc3_ = 35;
               _loc2_ = 50;
         }
      }
      this.mWorld.mHud.mSilentMessages = true;
      _loc3_ = _loc3_ - 1;
      while(_loc3_)
      {
         ++this.mLevel;
         _loc3_ = _loc3_ - 1;
      }
      _loc2_ = _loc2_ - 1;
      while(_loc2_)
      {
         ++this.mMultiplier;
         _loc2_ = _loc2_ - 1;
      }
      this.mWorld.mHud.mSilentMessages = false;
   }
